import { useState } from 'react';
import { JxTagInput, JxChip, JxEmptyState } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  label?: string;
  placeholder?: string;
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultTags = [],
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const applyTags = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const removeTag = (tag: string) => {
    applyTags(tags.filter((item) => item !== tag));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
      <JxTagInput
        ariaLabel={label}
        placeholder={placeholder}
        value={tags}
        onValueChange={applyTags}
      />
      {tags.length === 0 ? (
        <JxEmptyState
          title="Тегов пока нет"
          message="Добавьте первый тег, чтобы статью было проще найти."
        />
      ) : (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
        >
          {tags.map((tag) => (
            <JxChip key={tag} role="listitem" active removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

